<?php
namespace App\Services;
use App\Models\GradingScale;use App\Models\SchoolSetting;use App\Models\Student;use App\Models\Term;use Illuminate\Support\Facades\DB;
class TermReportCalculator {public static function settings(int $schoolId):array{$s=SchoolSetting::where('school_id',$schoolId)->whereIn('key',['report_level','report_pass_mark','report_secondary_best','report_show_position','report_show_fees','report_show_attendance','report_show_promotion','report_footer'])->pluck('value','key');return ['level'=>$s['report_level']??'primary','pass'=>(float)($s['report_pass_mark']??50),'best'=>(int)($s['report_secondary_best']??8),'show_position'=>($s['report_show_position']??'enabled')==='enabled','show_fees'=>($s['report_show_fees']??'enabled')==='enabled','show_attendance'=>($s['report_show_attendance']??'enabled')==='enabled','show_promotion'=>($s['report_show_promotion']??'disabled')==='enabled','footer'=>$s['report_footer']??''];}public static function student(Student $student,Term $term):array{$settings=self::settings($student->school_id);$scales=GradingScale::where('school_id',$student->school_id)->get();$marks=DB::table('exam_marks')->join('exam_papers','exam_papers.id','=','exam_marks.exam_paper_id')->join('exams','exams.id','=','exam_papers.exam_id')->join('exam_paper_submissions','exam_paper_submissions.exam_paper_id','=','exam_papers.id')->join('subjects','subjects.id','=','exam_papers.subject_id')->where(['exam_marks.student_id'=>$student->id,'exams.term_id'=>$term->id,'exam_paper_submissions.status'=>'approved'])->select('subjects.name',DB::raw('sum(exam_marks.score) as score'),DB::raw('sum(exam_papers.maximum_score) as maximum'))->groupBy('subjects.id','subjects.name')->get()->map(function($row)use($scales){$percentage=$row->maximum?round($row->score/$row->maximum*100,2):0;$scale=$scales->first(fn($s)=>$percentage>=$s->minimum_percentage&&$percentage<=$s->maximum_percentage);return ['subject'=>$row->name,'score'=>$row->score,'maximum'=>$row->maximum,'percentage'=>$percentage,'grade'=>$scale?->grade??'-','comment'=>$scale?->remark??''];});$ranked=$marks->sortByDesc('percentage');$used=$settings['level']==='secondary'?$ranked->take($settings['best']):$ranked;$average=$used->count()?round($used->avg('percentage'),2):0;return compact('settings','marks','average')+['passed'=>$average>=$settings['pass'],'aggregate'=>$used->sum(fn($m)=>match($m['grade']){'A'=>1,'B'=>2,'C'=>3,'D'=>4,'E'=>5,'F'=>6,default=>0})];}}
